// Relocation: Adjusting Addresses at Link/Load Time

// Relocation Entry Structure (Conceptual)
struct Rela {
    long offset;    // Location in code/data to patch
    long sym_idx;   // Index of Symbol (S)
    long addend;    // Stored offset (A)
};

// Relocation Formulae Applied by Linker:
// Absolute Relocation:
// New Value = S + A;

// PC-Relative Relocation (P = Offset address):
// New Value = S + A - P;
